<?php require_once __DIR__.'/../includes/bootstrap.php'; require_login(); $uid=(int)(current_user()['id']??0); $search=trim((string)($_GET['q']??'')); if(is_admin()){if($search!==''){$q=$pdo->prepare("SELECT a.*,COUNT(t.id) track_count,u.username owner_username FROM albums a LEFT JOIN tracks t ON t.album_id=a.id LEFT JOIN users u ON u.id=a.owner_user_id WHERE a.deleted_at IS NULL AND (a.title LIKE ? OR a.artist LIKE ?) GROUP BY a.id ORDER BY a.created_at DESC");$like='%'.$search.'%';$q->execute([$like,$like]);$albums=$q->fetchAll();}else{$albums=$pdo->query("SELECT a.*,COUNT(t.id) track_count,u.username owner_username FROM albums a LEFT JOIN tracks t ON t.album_id=a.id LEFT JOIN users u ON u.id=a.owner_user_id WHERE a.deleted_at IS NULL GROUP BY a.id ORDER BY a.created_at DESC")->fetchAll();}}else{$sql='SELECT a.*,COUNT(t.id) track_count FROM albums a LEFT JOIN tracks t ON t.album_id=a.id LEFT JOIN album_collaborators ac ON ac.album_id=a.id AND ac.user_id=? WHERE a.deleted_at IS NULL AND (a.owner_user_id=? OR ac.user_id IS NOT NULL)';$params=[$uid,$uid];if($search!==''){$sql.=' AND (a.title LIKE ? OR a.artist LIKE ?)';$like='%'.$search.'%';$params[]=$like;$params[]=$like;}$sql.=' GROUP BY a.id ORDER BY a.created_at DESC';$q=$pdo->prepare($sql);$q->execute($params);$albums=$q->fetchAll();} $showDashboardStatistics=get_setting('dashboard_statistics_cards','1')==='1';
$dashboard=['albums'=>count($albums),'tracks'=>0,'shares'=>0,'plays'=>0];
if($showDashboardStatistics){
try{
 [$metricAccess,$metricArgs]=accessible_album_condition('a');
 $q=$pdo->prepare("SELECT COUNT(DISTINCT a.id) albums,COUNT(DISTINCT t.id) tracks,COUNT(DISTINCT sh.id) shares FROM albums a LEFT JOIN tracks t ON t.album_id=a.id LEFT JOIN shares sh ON sh.album_id=a.id WHERE a.deleted_at IS NULL AND {$metricAccess}");
 $q->execute($metricArgs);$r=$q->fetch();$dashboard['albums']=(int)($r['albums']??0);$dashboard['tracks']=(int)($r['tracks']??0);$dashboard['shares']=(int)($r['shares']??0);
 $q=$pdo->prepare("SELECT COALESCE(SUM(s.event_count),0) FROM statistics_daily s JOIN albums a ON a.id=s.album_id WHERE s.event_type='track_play' AND a.deleted_at IS NULL AND {$metricAccess}");
 $q->execute($metricArgs);$dashboard['plays']=(int)$q->fetchColumn();
}catch(Throwable $e){}
}
render_header('Alben',true); ?><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h2 mb-1">Alben</h1><p class="text-body-secondary mb-0"><?=e(t('text.musikalben.hochladen.gestalten.und.teilen'))?></p></div><div class="d-flex gap-2"><?php if(is_admin()):?><a class="btn btn-outline-secondary" href="trash.php"><i class="bi bi-trash3 me-1"></i><?=e(t('nav.trash'))?></a><?php endif?><button class="btn btn-outline-primary" type="button" data-open-direct-upload><i class="bi bi-cloud-arrow-up me-1"></i><?=e(t('text.album.direkt.hochladen'))?></button><a class="btn btn-primary" href="album_edit.php"><i class="bi bi-plus-lg me-1"></i><?=e(t('text.neues.album'))?></a></div></div><?php if($showDashboardStatistics):?><div class="row g-3 mb-4"><?php foreach([['albums','dashboard.albums','bi-disc'],['tracks','dashboard.tracks','bi-music-note-list'],['shares','dashboard.shares','bi-link-45deg'],['plays','dashboard.plays','bi-play-circle']] as [$key,$label,$icon]):?><div class="col-6 col-lg-3"><div class="card shadow-sm"><div class="card-body py-3"><div class="small text-body-secondary"><i class="bi <?=$icon?> me-1"></i><?=e(t($label))?></div><div class="h3 mb-0 mt-1"><?=number_format($dashboard[$key],0,',','.')?></div></div></div></div><?php endforeach?></div><?php endif?><div class="row g-4"><?php foreach($albums as $a):?><div class="col-sm-6 col-lg-4"><div class="card h-100 shadow-sm"><?php if($a['cover_file']):?><a href="album_edit.php?id=<?=$a['id']?>" aria-label="Album <?=e($a['title'])?> verwalten"><img src="<?=base_url('uploads/covers/'.$a['cover_file'])?>" class="card-img-top" style="aspect-ratio:1/1;object-fit:cover" alt="Cover <?=e(t('text.von'))?> <?=e($a['title'])?>"></a><?php else:?><a href="album_edit.php?id=<?=$a['id']?>" class="text-decoration-none" aria-label="Album <?=e($a['title'])?> verwalten"><div class="cover-placeholder rounded-0">♪</div></a><?php endif?><div class="card-body"><h2 class="h5"><?=e($a['title'])?></h2><p class="text-body-secondary mb-2"><?=e($a['artist'])?> · <?=$a['track_count']?> <?=current_language()==='en'?'tracks':(current_language()==='fr'?'pistes':t('text.titel'))?></p><?php if(is_admin()):$isOwn=(int)$a['owner_user_id']===$uid;?><div class="small mb-3"><span class="badge <?=$isOwn?'text-bg-secondary':'text-bg-info'?>"><?=$isOwn?t('text.eigenes.album'):t('text.fremdes.album')?></span><span class="text-body-secondary ms-2"><?=e(t('text.erstellt.von'))?> <?=e($a['owner_username']?:t('common.unknown'))?></span></div><?php endif?><div class="d-flex gap-2"><a class="btn btn-sm btn-primary" href="album_edit.php?id=<?=$a['id']?>"><?=e(t('text.verwalten'))?></a><a class="btn btn-sm btn-outline-secondary" target="_blank" href="<?=base_url('share.php?album_id='.$a['id'])?>"><?=e(t('text.vorschau'))?></a></div></div></div></div><?php endforeach?><?php if(!$albums):?><div class="col-12"><div class="alert alert-info"><?= $search!=='' ? t('text.keine.alben.fur.diese.suche.gefunden') : t('albums.empty') ?></div></div><?php endif?></div>
